// Degraded-run alert payload
return [{
  json: {
    text: `🚨 *Nordgreen monitor degraded*\nFetch returned no products or failed. Source may be blocked, rate-limited, or changed shape. Check manually.`
  }
}];

// Compute diffs against previous state, using n8n's built-in workflow static data.
// No filesystem needed — this persists automatically across scheduled runs.



const staticData = $getWorkflowStaticData('global');



if (!staticData.previousState) {
    staticData.previousState = {}; // first run — everything will be 'new'
}


const previousState = staticData.previousState;



//console.log('DEBUG: previousState has', Object.keys(previousState).length, 'stored products');

const isFirstRun = Object.keys(previousState).length === 0; //added this for first run init.

const normalized = $('Normalize + Hash').first().json.normalized;
const diffs = [];

for (const { record, hash } of normalized) {
  const pid = record.id;
  const prev = previousState[pid];

    // DEBUG — place it here, right after prev is read, before anything is overwritten
  if (pid === '10873400197463') {
    console.log('Stored hash:', prev?.hash, '| Incoming hash:', hash, '| Match:', prev?.hash === hash);
  }

  if (!prev) {
    diffs.push({ type: 'new_product', product_id: pid, title: record.title, old: null, new: record });
  } else if (prev.hash !== hash) {
    const oldRecord = prev.record;
    let priceDelta = null;
    if (oldRecord.min_price != null && record.min_price != null) {
      priceDelta = Math.abs(record.min_price - oldRecord.min_price);
    }

    // Detect stock transitions explicitly — higher-signal than generic "other_change"
    let diffType = null;
    if (oldRecord.available === true && record.available === false) {
      diffType = 'stock_out';
    } else if (oldRecord.available === false && record.available === true) {
      diffType = 'restock';
    } else if (oldRecord.on_sale === false && record.on_sale === true) {
      diffType = 'sale_started';
    } else if (oldRecord.on_sale === true && record.on_sale === false) {
      diffType = 'sale_ended';
    } else if (priceDelta && priceDelta > 0) {
      diffType = 'price_change';
    } else {
      diffType = 'other_change';
    }
    // Deterministic pre-filter: ignore sub-$1 price noise entirely (never reaches Claude)
    if (priceDelta !== null && priceDelta > 0 && priceDelta < 1.0) {
      const priceOnlyDiff = JSON.stringify({...oldRecord, min_price: null, max_price: null}) ===
                            JSON.stringify({...record, min_price: null, max_price: null});
      if (priceOnlyDiff) {
        previousState[pid] = { hash, record };
        continue;
      }
    }
      diffs.push({
      type: diffType,
      product_id: pid,
      title: record.title,
      old: oldRecord,
      new: record
    });
  } else {
    // unchanged — still refresh stored copy (harmless, keeps things simple)
  }

  previousState[pid] = { hash, record };
}

// staticData is a live reference — mutating it above already persists the update.
// n8n saves static data automatically when the workflow execution completes.

return [{ json: { diffs: isFirstRun ? [] : diffs, isBaselineRun: isFirstRun, baselineCount: normalized.length } }];

// Standardized log entry for baseline runs and genuinely quiet runs
const isBaseline = $json.isBaselineRun;

return [{
  json: {
    timestamp: new Date().toISOString(),
    status: isBaseline ? 'baseline_established' : 'no_changes',
    diffs_detected: 0,
    diffs_reported: 0,
    detail: isBaseline
      ? `Baseline established — captured ${$json.baselineCount} products, nothing to compare yet`
      : 'No diffs detected this run'
  }
}];

// Parse Claude's verdicts and merge back with the diffs.
// Finds the text block dynamically (Claude Sonnet 5 returns a 'thinking'
// block before the 'text' block, so content[0] is NOT the answer).

const diffs = $('Compute Diffs').first().json.diffs;
const raw = $input.first().json;

let rawText = null;

if (raw?.error) {
  throw new Error('Claude API error: ' + JSON.stringify(raw.error));
}

const contentBlocks = raw?.content || raw?.body?.content;

if (Array.isArray(contentBlocks)) {
  const textBlock = contentBlocks.find(b => b.type === 'text');
  if (textBlock?.text) {
    rawText = textBlock.text;
  }
}

if (!rawText) {
  console.log('Unexpected Claude response shape:', JSON.stringify(raw).slice(0, 500));
}

if (raw?.stop_reason === 'max_tokens') {
  console.log('WARNING: Claude response was truncated (stop_reason: max_tokens). Increase max_tokens in Build Claude Payload.');
}

let parsed;
if (!rawText) {
  parsed = { results: diffs.map(d => ({
    product_id: d.product_id,
    worth_reporting: true,
    category: 'unclassified',
    reasoning: 'Could not read Claude response (unexpected shape) — flagging for manual review.'
  })) };
} else {
  let content = rawText.trim().replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '').trim();
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    parsed = { results: diffs.map(d => ({
      product_id: d.product_id,
      worth_reporting: true,
      category: 'unclassified',
      reasoning: 'Claude response could not be parsed as JSON (possibly truncated) — flagging for manual review.'
    })) };
  }
}

const verdictsById = Object.fromEntries(parsed.results.map(v => [v.product_id, v]));

const annotated = diffs.map(d => ({
  ...d,
  verdict: verdictsById[d.product_id] || {
    worth_reporting: true,
    category: 'unclassified',
    reasoning: 'No verdict returned for this item — flagging for manual review.'
  }
}));

const material = annotated.filter(d => d.verdict.worth_reporting);
const noise = annotated.filter(d => !d.verdict.worth_reporting);

return [{ json: { material, noise, allAnnotated: annotated } }];

// Format the Slack message from material diffs
const material = $json.material;
const lines = [`🔍 *Nordgreen monitor — ${material.length} change(s) detected*\n`];
for (const d of material) {
  lines.push(`• *${d.title}* — \`${d.verdict.category}\`\n   ${d.verdict.reasoning}`);
}
return [{ json: { text: lines.join('\n') } }];

// Standardized log entry for runs where diffs were detected and judged by Claude
const material = $json.material || [];
const noise = $json.noise || [];

return [{
  json: {
    timestamp: new Date().toISOString(),
    status: 'OK',
    diffs_detected: material.length + noise.length,
    diffs_reported: material.length,
    detail: `${material.length + noise.length} diff(s) detected, ${material.length} reported, ${noise.length} filtered as noise`
  }
}];

// Build the Claude API request payload as a proper object.
// Kept separate from the HTTP node so the JSON is never double-stringified.

const diffs = $json.diffs;

const systemPrompt = `You are a competitive intelligence analyst for a marketing agency.
You will be shown a batch of detected changes on a competitor's e-commerce site.

For EACH change, decide if it is worth alerting a human about.

Report as material (worth_reporting: true):
- New product launches
- Price changes of real magnitude (not rounding/currency noise)
- Products going out of stock or back in stock
- Changes signaling a strategic shift (new product category, new tags suggesting new positioning)
- A product going on sale or a sale ending
- Restocks after being out of stock

Do NOT report as material (worth_reporting: false):
- Cosmetic text changes (typo fixes, minor description rewording)
- Negligible price fluctuations
- Metadata-only changes with no customer-facing impact

Respond ONLY with valid JSON, no preamble, in this exact shape:
{"results": [{"product_id": "...", "worth_reporting": true, "category": "new_product|price_change|stock_change|other", "reasoning": "one sentence"}]}`;

const diffSummaries = diffs.map(d => ({
  product_id: d.product_id,
  title: d.title,
  type: d.type,
  old_price: d.old ? d.old.min_price : null,
  new_price: d.new.min_price,
  on_sale: d.new.on_sale,
  compare_at_price: d.new.compare_at_price,
  old_available: d.old ? d.old.available : null,
  new_available: d.new.available
}));

const userMessage = "Batch of detected changes:\n\n" + JSON.stringify(diffSummaries, null, 2);

const payload = {
  model: "claude-sonnet-5",
  max_tokens: 8000,
  system: systemPrompt,
  messages: [
    { role: "user", content: userMessage }
  ]
};

return [{ json: payload }];

// Normalize + hash each product (deterministic, no AI cost)
// Pure-JS hash (no 'crypto' module) since n8n's sandbox blocks Node built-ins by default

function simpleHash(str) {
  // djb2 hash - fast, deterministic, plenty collision-resistant for this use case
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash; // convert to 32-bit int
  }
  return hash.toString(16);
}

function normalizeProduct(p) {
  const variants = p.variants || [];
  const prices = variants.map(v => parseFloat(v.price)).filter(p => !isNaN(p));
  const compareAtPrices = variants
    .map(v => v.compare_at_price ? parseFloat(v.compare_at_price) : null)
    .filter(p => p !== null && !isNaN(p));

  const min_price = prices.length ? Math.min(...prices) : null;
  const max_compare_at = compareAtPrices.length ? Math.max(...compareAtPrices) : null;
  const on_sale = max_compare_at !== null && min_price !== null && max_compare_at > min_price;

  return {
    id: String(p.id),
    title: p.title || '',
    handle: p.handle || '',
    product_type: p.product_type || '',
    tags: p.tags || '',
    min_price,
    max_price: prices.length ? Math.max(...prices) : null,
    compare_at_price: max_compare_at,
    on_sale,
    variant_count: variants.length,
    available: variants.some(v => v.available)
  };
}

function hashRecord(record) {
  const fingerprint = JSON.stringify(record, Object.keys(record).sort());
  return simpleHash(fingerprint);
}

const products = $input.first().json.products;
const normalized = products.map(p => {
  const record = normalizeProduct(p);
  return { record, hash: hashRecord(record) };
});

return [{ json: { normalized } }];

return [{
  json: {
    timestamp: new Date().toISOString(),
    status: 'Degraded',
    diffs_detected: 0,
    diffs_reported: 0,
    detail: 'Fetch failed or returned no products — see Slack alert for details'
  }
}];
